"""
app/generators/kql_gen.py
-------------------------
Generates Microsoft Fabric KQL Database schemas, telemetry streaming tables,
and KQL Querysets for millisecond time-series analytics.
"""

from __future__ import annotations

import base64
from typing import Any


def generate_kql_database_script(
    database_name: str,
    tables: list[dict[str, Any]],
) -> str:
    """
    Generates Kusto Query Language (.kql) DDL script creating tables and mappings.
    """
    lines = [
        f"// KQL Database Schema: {database_name}",
        "// Auto-generated by Fabric AI Studio\n",
    ]

    for tbl in tables:
        tname = tbl.get("name", "TelemetryEvents")
        cols = tbl.get("columns", [])
        col_specs = []

        for c in cols:
            cname = c.get("name", "timestamp")
            ctype = c.get("type", "datetime").lower()
            kql_type = "string"
            if "time" in ctype or "date" in ctype:
                kql_type = "datetime"
            elif "int" in ctype:
                kql_type = "int"
            elif "long" in ctype or "bigint" in ctype:
                kql_type = "long"
            elif "double" in ctype or "float" in ctype or "decimal" in ctype:
                kql_type = "real"
            elif "bool" in ctype:
                kql_type = "bool"
            elif "json" in ctype or "dict" in ctype:
                kql_type = "dynamic"

            col_specs.append(f"{cname}:{kql_type}")

        lines.append(f".create-merge table {tname} ({', '.join(col_specs)})\n")
        lines.append(f".alter table {tname} policy retention softdelete = 30d recoverability = enabled\n")

    return "\n".join(lines)


def package_kql_definition_parts(
    kql_script: str,
) -> list[dict[str, Any]]:
    """
    Packages KQL script into Base64 inline definition parts format for Fabric API.
    """
    b64_kql = base64.b64encode(kql_script.encode("utf-8")).decode("utf-8")
    return [
        {
            "path": "database.kql",
            "payload": b64_kql,
            "payloadType": "InlineBase64",
        }
    ]
